// ITRANS → Devanagari. Expected outputs are written by hand from the
// ITRANS 5.3 table and standard Devanagari spelling (TECH_SPEC §5.2, §5.3),
// never generated by the converter.

import { describe, expect, it } from "vitest";
import { transliterate } from "../../src/conversion/itrans";

const t = (s: string) => transliterate(s).text;

describe("vowels and consonants (§5.2)", () => {
  it.each([
    ["a aa A i ii I u uu U", "अ आ आ इ ई ई उ ऊ ऊ"],
    ["RRi R^i RRI R^I LLi L^i", "ऋ ऋ ॠ ॠ ऌ ऌ"],
    ["e ai o au", "ए ऐ ओ औ"],
    [
      "ka kA ki kI ku kU kRRi kR^I ke kai ko kau",
      "क का कि की कु कू कृ कॄ के कै को कौ",
    ],
    ["ka kha ga gha ~Na", "क ख ग घ ङ"],
    ["cha Cha chha ja jha ~na JNa", "च छ छ ज झ ञ ञ"],
    ["Ta Tha Da Dha Na", "ट ठ ड ढ ण"],
    ["ta tha da dha na pa pha ba bha ma", "त थ द ध न प फ ब भ म"],
    ["ya ra la va wa sha Sha shha sa ha La lda", "य र ल व व श ष ष स ह ळ ळ"],
    ["xa kSha GYa j~na dnya", "क्ष क्ष ज्ञ ज्ञ ज्ञ"],
  ])("%s", (input, expected) => {
    expect(t(input)).toBe(expected);
  });

  it("writes a virama on a consonant without a vowel", () => {
    expect(t("agnim")).toBe("अग्निम्");
    expect(t("vAk-pati")).toBe("वाक्-पति");
    expect(t("tat")).toBe("तत्");
  });

  it("forms conjuncts", () => {
    expect(t("sahasra")).toBe("सहस्र");
    expect(t("kRRiShNa")).toBe("कृष्ण");
    expect(t("lakShmI")).toBe("लक्ष्मी");
    expect(t("yaj~naH")).toBe("यज्ञः");
    expect(t("sha~Nkara")).toBe("शङ्कर");
  });

  it("handles anusvara, visarga, chandrabindu, avagraha, OM and dandas", () => {
    expect(t("puruShaH")).toBe("पुरुषः");
    expect(t("ahaM")).toBe("अहं");
    expect(t("tA.N")).toBe("ताँ");
    expect(t("so.ahaM")).toBe("सोऽहं");
    expect(t("OM namaH")).toBe("ॐ नमः");
    expect(t("iti | iti ||")).toBe("इति । इति ॥");
  });

  it("uses .h for an explicit virama and {} as a separator", () => {
    expect(t("k.h")).toBe("क्");
    expect(t("ka{}i")).toBe("कइ");
    expect(t("k{}ha")).toBe("क्ह");
  });

  it("converts digits by default, or keeps them", () => {
    expect(t("10.090.01")).toBe("१०.०९०.०१");
    expect(transliterate("10", { devanagariDigits: false }).text).toBe("10");
  });

  it("passes through spaces, punctuation and existing Unicode", () => {
    expect(t("rAma, sItA; (ka) - ?")).toBe("राम, सीता; (क) - ?");
    expect(t("deva देव")).toBe("देव देव");
  });
});

describe("Vedic accents (§5.3)", () => {
  it("converts Ṛgveda 1.1.1", () => {
    expect(t("a_gnimii'Le pu_rohi'taM ya_j~nasya' de_vamR^i_tvija'm")).toBe(
      "अ॒ग्निमी॑ळे पु॒रोहि॑तं य॒ज्ञस्य॑ दे॒वमृ॒त्विज॑म्",
    );
  });

  it("maps _ ' ''' to U+0952, U+0951, U+1CDA", () => {
    expect(t("sa_")).toBe("स॒");
    expect(t("sa'")).toBe("स॑");
    expect(t("svAhA'''")).toBe("स्वाहा᳚");
    expect(t("svAhA'''")).not.toContain("॓");
  });

  it("writes anusvara, visarga and chandrabindu before the accent, typed either way", () => {
    for (const input of ["bhUmiM'", "bhUmi'M"]) expect(t(input)).toBe("भूमिं॑");
    for (const input of ["vaH_", "va_H"]) expect(t(input)).toBe("वः॒");
    for (const input of ["tA.N'", "tA'.N"]) expect(t(input)).toBe("ताँ॑");
  });

  it("flags apostrophe runs of the wrong length and leaves them as typed", () => {
    for (const run of ["''", "''''"]) {
      const r = transliterate(`sa${run}`);
      expect(r.text).toBe(`स${run}`);
      expect(r.issues).toHaveLength(1);
      expect(r.issues[0]).toMatchObject({ offset: 2, length: run.length });
    }
    expect(transliterate("sa__").issues).toHaveLength(1);
  });

  it("flags an accent that does not follow a vowel", () => {
    for (const input of ["'sa", "sa '", "k'"]) {
      const r = transliterate(input);
      expect(r.issues).toHaveLength(1);
      expect(r.issues[0]!.message).toMatch(/must follow a vowel/);
      expect(r.text).toContain("'");
    }
  });
});

describe("Taittirīya anusvara (gm)/(gg)", () => {
  it("writes U+A8F3 and U+A8F4, and an accent may follow", () => {
    const r = transliterate("sarasA(gm) bhU'yAsa_(gg)_ svAhA'''");
    expect(r.text).toBe("सरसा\uA8F3 भू॑यास॒\uA8F4॒ स्वाहा᳚");
    expect(r.issues).toEqual([]);
  });

  it("leaves other parenthesised text alone", () => {
    expect(t("(gam) (g)")).toBe("(गम्) (ग्)");
  });
});

describe("Baraha spellings", () => {
  it("accepts Ru, RU, ~g, ~j and ~M as in Baraha", () => {
    // Rigveda 10.90.1 typed as in the Baraha source.
    expect(t("sa bhUmi'M vi_shvato' vRu_tvAtya'tiShThaddashA~ggu_lam")).toBe(
      "स भूमिं॑ वि॒श्वतो॑ वृ॒त्वात्य॑तिष्ठद्दशाङ्गु॒लम्",
    );
    expect(t("RuShi RUkAra")).toBe("ऋषि ॠकार");
    expect(t("tilA~jjuhomi j~jAna jyAyA'~Mshcha")).toBe(
      "तिलाञ्जुहोमि ज्ञान ज्याया\u0901\u0951श्च",
    );
    expect(transliterate("vRu_tvA ~ggu ~jja ~M").issues).toEqual([]);
  });
});

describe("unknown input", () => {
  it("passes unknown Latin letters through and reports them", () => {
    const r = transliterate("raBa");
    expect(r.text).toBe("रBअ");
    expect(r.issues).toEqual([
      { offset: 2, length: 1, message: '"B" is not ITRANS' },
    ]);
  });

  it("reports nothing for clean input", () => {
    expect(transliterate("sahasrashIrShA puruShaH |").issues).toEqual([]);
  });
});
